        let listener = tokio::net::TcpListener::bind(("127.0.0.1", 0))
            .await
            .unwrap();
        let endpoint = format!("http://{}/images", listener.local_addr().unwrap());
        tokio::spawn(async move {
            let Ok((socket, _)) = listener.accept().await else {
                return;
            };
            let _keep_open = socket;
            std::future::pending::<()>().await;
        });

        let client = OpenRouterImageClient::with_endpoint("secret", endpoint)
            .with_timeout(Duration::from_millis(10));
        let error = client
            .generate(
                &ImageRequest::new("provider/model", "a cat"),
                &CancellationToken::new(),
                1024,
            )
            .await
            .unwrap_err();
        assert_eq!(error, ImageError::Timeout { timeout_ms: 10 });
