    #[test]
    fn response_parser_accepts_all_observed_shapes() {
        let direct = parse_response(&json!({
            "data": [{ "b64_json": "QUJD", "revised_prompt": "better" }],
            "usage": { "cost": 0.1 },
        }))
        .unwrap();
        assert_eq!(direct.base64.as_deref(), Some("QUJD"));
        assert_eq!(direct.revised_prompt.as_deref(), Some("better"));
        assert_eq!(direct.cost_usd, Some(0.1));

        let nested = parse_response(
            &json!({ "data": [{ "image_url": { "url": "data:image/webp;base64,QUJD" } }] }),
        )
        .unwrap();
        assert_eq!(nested.base64.as_deref(), Some("QUJD"));
        assert_eq!(nested.media_type.as_deref(), Some("image/webp"));

        let remote =
            parse_response(&json!({ "data": [{ "url": "https://cdn.test/a.png" }] })).unwrap();
        assert_eq!(remote.remote_url.as_deref(), Some("https://cdn.test/a.png"));
        assert_eq!(
            parse_response(&json!({ "data": [{}] })),
            Err(ImageError::NoImage)
        );
    }

    #[test]
    fn remote_ip_policy_rejects_private_link_local_and_reserved_ranges() {
        for ip in [
            "127.0.0.1",
            "10.0.0.1",
            "169.254.169.254",
            "192.0.2.1",
            "224.0.0.1",
            "::1",
            "fc00::1",
            "fe80::1",
            "2001:db8::1",
            "2001:100::1",
            "2002:0808:0808::1",
            "3fff::1",
            "::ffff:127.0.0.1",
        ] {
            assert!(!is_public_ip(ip.parse().unwrap()), "{ip}");
        }
        for ip in ["1.1.1.1", "8.8.8.8", "2606:4700:4700::1111"] {
            assert!(is_public_ip(ip.parse().unwrap()), "{ip}");
        }
    }
